import {helpers,acceptsAnswer} from './help-content.mjs';
import {guides,avatars,portrait,gardenScene} from './companions.mjs';
import {entrances,storyNodes} from './story-content.mjs';
import {ensureGarden,currentVisit,entranceById,storyDescribe} from './garden-core.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const heading=(title,body)=>`<div class="page-heading"><a href="#home" class="back">← Back to the garden</a><h1>${esc(title)}</h1><p>${esc(body)}</p></div>`;
const named=(s,g)=>esc(s.replaceAll('{guide}',g.name));
const guideOf=s=>guides.find(g=>g.id===s.garden.guide);
export function companionLink(state){const g=guideOf(state);return `${portrait(g.id,true)}<span>With ${g.name}</span>`;}
export function guideRail(state,line){const g=guideOf(state);return `<aside class="guide-rail"><div class="guide-face">${portrait(g.id)}</div><h2>${g.name}</h2><p>${line?named(line,g):esc(g.hello)}</p><a href="#companions">Change companions</a><p class="tiny">Read, draw, talk, or take a break. You can find your own way.</p></aside>`;}
const pathIcon=id=>({creature:'✧',message:'✉',shelter:'⌂',cafe:'♧'}[id]);
export function gardenHome(state,persist){
 const g=ensureGarden(state),v=currentVisit(state);
 return `<section class="garden-opening"><div class="garden-introduction"><p class="place-name">First morning in the Learning Garden</p><h1>The rain has stopped.<br>What will you discover?</h1><p>A tiny trail. A letter on a twig. A shelter waiting to be imagined. There’s more than one way into this story.</p><div class="hero-actions"><a class="primary" href="#storm">Choose a path</a><a class="text-button" href="#companions">Choose your companions</a></div><p class="tiny">${persist?'Your place is remembered in this browser.':'Saving is off. Your place lasts while this page stays open.'}</p></div><div class="garden-map">${gardenScene()}<button type="button" class="map-sign sign-creature" data-start-path="creature"><span>${pathIcon('creature')}</span>Follow a creature</button><button type="button" class="map-sign sign-message" data-start-path="message"><span>${pathIcon('message')}</span>Investigate a note</button><button type="button" class="map-sign sign-shelter" data-start-path="shelter"><span>${pathIcon('shelter')}</span>Make a hideaway</button></div></section><section class="welcome-companion"><div>${portrait(g.guide)}</div><blockquote><p>“${esc(guideOf(state).hello)}”</p><footer>${guideOf(state).name}, your companion <a href="#companions">Change</a></footer></blockquote><div class="explorer-stamp">${portrait(g.avatar,true)}<span>Your explorer</span></div></section>${v?`<div class="resume-strip"><span>${v.finished?'An idea is waiting to go with you.':`Your visit is waiting: ${esc(entranceById(v.entrance).title)}.`}</span><a class="secondary" href="#storm/${v.finished?'end':'play'}">${v.finished?'See your ending':'Continue our visit'}</a></div>`:''}<section class="cafe-invitation"><div class="cafe-sketch" aria-hidden="true">☾<span>ALMOST-RIGHT CAFÉ</span>♧</div><div><p class="place-name">A new little adventure</p><h2>The cupboard is full of surprises.</h2><p>Moon noodles? Fresh out. Warm, crunchy cloud toast? We might have just the thing. Open a make-believe café with wonderfully peculiar orders.</p><button class="primary" data-start-path="cafe">Open the Almost-Right Café</button></div></section><section class="number-destination"><div class="number-emblem" aria-hidden="true">+ × ÷<br><span>✿</span></div><div><h2>Number Garden is still growing.</h2><p>Visit the seven math patches for check-ins, multiplication, picture playgrounds, and things to wonder about.</p><a class="secondary" href="#numbers">Explore Number Garden</a></div></section><p class="tiny garden-note">Explore together. Every path is open. No timer, grades, or need to finish everything.</p>`;
}
export function companionPicker(state){
 const g=ensureGarden(state);
 return `${heading('Who’s coming with you?','Choose a guide and an explorer. You can change either whenever you like. No name or profile is needed.')}<section class="companion-section"><h2>Your guide</h2><p class="tiny">Every guide explores every path with you.</p><div class="companion-options">${guides.map(x=>`<button class="companion-option ${g.guide===x.id?'selected':''}" data-guide="${x.id}" aria-pressed="${g.guide===x.id}">${portrait(x.id)}<strong>${x.name}</strong><span class="tiny">${x.pronouns}</span><span>${esc(x.description)}</span><span class="choice-tick">${g.guide===x.id?'✓ Chosen':'Choose '+x.name}</span></button>`).join('')}</div></section><section class="companion-section"><h2>Your explorer</h2><p class="tiny">Choose the character you would like to be. This choice is separate from your guide.</p><div class="companion-options">${avatars.map(x=>`<button class="companion-option explorer-option ${g.avatar===x.id?'selected':''}" data-avatar="${x.id}" aria-pressed="${g.avatar===x.id}">${portrait(x.id)}<strong>${x.name}</strong><span>${x.description}</span><span class="choice-tick">${g.avatar===x.id?'✓ Chosen':'Choose this explorer'}</span></button>`).join('')}</div></section><div class="summary-links"><a class="primary" href="#storm">Explore the first morning</a><a class="secondary" href="#home">Back to the garden</a></div>`;
}
export function storyHub(state,pending){
 const v=currentVisit(state),g=state.garden,want=entranceById(pending);
 const confirmation=want&&v&&!v.finished?`<section class="visit-decision" role="region" aria-label="A visit is waiting"><h2>You have a visit waiting.</h2><p>You were exploring “${esc(entranceById(v.entrance).title)}.” You can continue, or begin “${esc(want.title)}” and keep the earlier visit here.</p><div class="summary-links"><button class="primary" data-resume-visit="${v.id}">Continue the waiting visit</button><button class="secondary" data-new-visit="${want.id}">Begin this new path</button></div></section>`:'';
 return `${heading('Follow your curiosity','The Learning Garden has changed overnight. What catches your eye? Each path has its own ending; choose just one if you like.')}${confirmation}<div class="story-paths">${entrances.map(e=>`<article class="story-path path-${e.id}"><div class="path-sketch" aria-hidden="true">${pathIcon(e.id)}</div><h2>${esc(e.title)}</h2><p>${esc(e.invitation)}</p><button class="primary" data-start-path="${e.id}">${v&&!v.finished&&v.entrance===e.id?'Continue this path':g.visits.some(x=>x.entrance===e.id&&x.finished)?'Visit this path again':'Start here'}</button></article>`).join('')}</div>${g.visits.length?`<section class="visit-notebook"><h2>Your visits</h2><p class="tiny">Earlier visits stay here when you choose another entrance.</p><ul>${[...g.visits].reverse().map(x=>`<li><div><strong>${esc(entranceById(x.entrance).title)}</strong><span class="tiny">Visit ${x.id.split('-').at(-1)} · ${x.finished?'At an ending':'A place to return to'}</span></div><button class="secondary" data-resume-visit="${x.id}">${x.finished?'See the ending':'Continue'}</button></li>`).join('')}</ul></section>`:''}<a class="text-button" href="#numbers">Visit Number Garden instead</a>`;
}
function storyPicture(n){
 if(n.visual==='array')return `<div class="story-diagram"><div class="model-array" style="grid-template-columns:repeat(${n.diagram.cols},1fr)" role="img" aria-label="${n.diagram.rows} rows of ${n.diagram.cols} stones">${'<span></span>'.repeat(n.diagram.rows*n.diagram.cols)}</div></div>`;
 if(n.visual==='ruler'){
  const d=n.diagram,x=i=>24+i/d.max*360;
  return `<div class="story-diagram"><svg viewBox="0 0 410 105" role="img" aria-label="A ruler in centimetres, with a ribbon from ${d.start} to ${d.end}"><rect x="${x(d.start)}" y="15" width="${x(d.end)-x(d.start)}" height="24" rx="3" fill="#da8d8d"/><path d="M24 60H384" stroke="#183f39" stroke-width="2"/>${Array.from({length:d.max+1},(_,i)=>`<path d="M${x(i)} 55v12" stroke="#183f39"/><text x="${x(i)}" y="88" text-anchor="middle" font-size="14" fill="#183430">${i}</text>`).join('')}</svg></div>`;
 }
 return '';
}
const readingLabels=[['unobserved','Reading not observed'],['together','We read it together'],['independent','I read it independently']];
export function storyPage(state,d){
 const v=currentVisit(state),n=storyNodes[v.node],correct=acceptsAnswer(n,d.attempts.at(-1)),project=n.type==='project';
 const choices=project?(n.projectOptions||{creature:['A winding trail','A short trail','My own route'],message:['A picture','Words told to a helper','A picture and words'],shelter:['A tall doorway','A wide roof','My own shape']}[n.entrance]):null;
 return `${heading(entranceById(v.entrance).chapter||'First Morning',entranceById(v.entrance).title)}<div class="story-layout"><article class="story-sheet"><div class="story-chapter"><span>${esc(n.subject)} ${project?'· Imagine and make':'· A little investigation'}</span><span class="travelling-explorer">${portrait(state.garden.avatar,true)}</span></div><h2>${esc(n.title)}</h2><p class="story-body">${esc(n.body)}</p>${storyPicture(n)}<p class="story-question">${esc(n.prompt)}</p>${project?`<div class="project-invitation"><p>Your design, your choice. There is no right answer.</p><div class="project-choices" role="group" aria-label="Choose an idea">${choices.map(x=>`<button type="button" class="method ${d.designChoice===x?'selected':''}" data-design="${esc(x)}" aria-pressed="${d.designChoice===x}">${esc(x)}</button>`).join('')}</div>${d.designChoice?`<p class="design-note">An idea to take with you: <strong>${esc(d.designChoice)}</strong>.</p>`:''}<p class="tiny">Choosing or continuing records an invitation, not proof that you made something. You do not need to send us your work.</p><button class="primary" id="story-project-next">Take this idea to the ending</button></div>`:`${!correct?`<form id="story-answer-form" novalidate>${n.kind==='choice'?`<div class="choices story-choices" role="group" aria-label="Choose an answer">${n.choices.map((x,i)=>`<button type="button" class="choice ${d.choice===i?'selected':''}" data-story-choice="${i}" aria-pressed="${d.choice===i}">${esc(x)}</button>`).join('')}</div><button class="primary" type="submit">Try this idea</button>`:`<label for="story-answer" class="answer-label">Your answer${n.visual==='ruler'?' (centimetres)':''}</label><div class="answer-line"><input id="story-answer" type="text" inputmode="numeric" autocomplete="off" value="${esc(d.input)}" aria-describedby="story-error"><button type="submit" class="primary">Try my answer</button></div>`}<p class="tiny" id="story-error" role="alert">${esc(d.error||'')}</p></form>`:''}<div id="story-feedback" aria-live="polite">${correct?`<p class="feedback success">${esc(n.answerFeedback?.[d.attempts.at(-1)]||'That fits. What helped you find it?')}</p>`:d.attempts.length?`<p class="feedback">${esc(n.answerFeedback?.[d.attempts.at(-1)]||'An idea worth another look. You can try again, ask for a hint, or leave this question for now.')}</p>`:''}</div><div class="helper-offer ${d.attempts.length&&!correct?'after-miss':''}"><button class="secondary" id="story-help">Try a smaller example</button><p class="tiny">Your question waits here. A picture or little example might help.</p></div><div class="support-actions">${!d.hinted?'<button class="text-button" id="story-hint">A little hint</button>':''}${!d.revealed?'<button class="text-button" id="story-explain">Think it through together</button>':''}</div>${d.hinted?`<div class="hint"><strong>A little nudge</strong><p>${esc(n.hint)}</p></div>`:''}${d.revealed?`<div class="solution"><strong>One way to think about it</strong><p>${esc(n.explanation)}</p></div>`:''}${correct?`<fieldset class="story-method"><legend>How did you find it? Choose together.</legend><div class="method-grid">${[['knew','I knew it'],['worked','I worked it out'],['counted','I counted'],['together','We did it together']].map(([id,label])=>`<button type="button" class="method ${d.method===id?'selected':''}" data-story-method="${id}" aria-pressed="${d.method===id}">${label}</button>`).join('')}</div></fieldset>`:''}`}
 <details class="reading-record" ${n.subject==='Reading'?'open':''}><summary>How did we read this part?</summary><p class="tiny">This is separate from solving the question. Reading together is welcome. Leave “not observed” if you did not notice.</p><div class="reading-options" role="group" aria-label="Reading observation">${readingLabels.map(([id,label])=>`<button type="button" class="method ${d.reading===id?'selected':''}" data-reading="${id}" aria-pressed="${d.reading===id}">${label}</button>`).join('')}</div></details>
 ${!project?`<div class="next-row">${correct?`<button class="primary" id="story-next" ${!d.method?'disabled':''}>Keep exploring</button>`:'<button class="text-button" id="story-skip">Leave this question for now</button>'}<a class="text-button" href="#home">Pause in the garden</a></div>`:'<a class="text-button" href="#home">Pause in the garden</a>'}<p class="tiny story-progress-note">This path can finish on its own. No other path is required.</p></article>${guideRail(state,n.guide)}<aside class="story-wonder"><h3>Something to wonder</h3><p>${esc(correct||d.revealed||project?n.talk:'What do you notice? Where would you like to start?')}</p><p class="tiny">Talk, draw, or imagine together. The app does not score your explanation.</p></aside></div>`;
}
export function storyEnding(state){
 const v=currentVisit(state);if(!v?.finished)return storyHub(state);
 const e=entranceById(v.entrance),obs=state.garden.observations.filter(o=>o.visitId===v.id),idea=Object.values(v.drafts).find(d=>d.designChoice)?.designChoice;
 return `${heading('A place to pause.','One path is a whole visit. You can stop here, take an idea with you, or follow a different curiosity.')}<div class="story-layout"><article class="story-sheet story-ending"><span class="ending-leaf" aria-hidden="true">✧</span><h2>${esc(e.ending.title)}</h2><p class="story-body">${esc(e.ending.body)}</p><section class="takeaway"><h3>${esc(e.ending.projectTitle)}</h3><p>${esc(e.ending.project)}</p>${idea?`<p class="design-note">Your chosen idea: ${esc(idea)}.</p>`:''}<p class="tiny">Entirely optional. Nothing to upload, photograph, or hand in.</p></section><div class="summary-links"><a class="primary" href="#home">Back to the Learning Garden</a><a class="secondary" href="#storm">Follow another curiosity</a></div><details><summary>Grown-ups: what we noticed on this visit</summary>${obs.map(storyEvidence).join('')}<a href="#notes">All grown-up notes</a></details></article>${guideRail(state,'{guide} says, “There’s always more to wonder about. This is a good place to pause.”')}</div>`;
}
function storyEvidence(o){return `<div class="evidence-item"><strong>${esc(o.title)} — ${esc(storyDescribe(o))}</strong><p>${esc(o.prompt)}</p><p>${o.status==='invitation'?'Project invitation only.':`Answers tried: ${esc(o.attempts.map(v=>o.choices?.[v]??v).join(', ')||'None')}.`}${o.helpUsed?' Smaller example opened.':''}${o.hinted?' Hint opened.':''}${o.revealed?' Explanation opened.':''}${o.familiar?' This task was seen on an earlier visit.':''}${o.knownFact?' A related fact appeared earlier.':''}${o.priorExposureUnknown?' Earlier fact familiarity was not recorded.':''}</p>${o.helper?`<p>Helper example: ${esc(helpers[o.nodeId]?.title||o.helper.exampleId)}. Example answers tried: ${esc(o.helper.attempts.map(v=>helpers[o.nodeId]?.choices?.[v]??v).join(', ')||'None')}. ${o.helper.revealed?'Example explanation opened. ' :''}Representation${o.helper.modelUsed?' used':' not used'}: ${o.helper.steps||0} steps currently counted${o.helper.spotlight!==null?', a detail spotlighted':''}.</p>`:''}${o.method?`<p>Answer method: ${esc({knew:'Reported knowing it',worked:'Worked it out',counted:'Counted',together:'Worked together'}[o.method]||o.method)}.</p>`:''}<p>Reading: ${o.reading==='independent'?'reported read independently':o.reading==='together'?'read together':'not observed'}.</p>${o.designChoice?`<p>Unscored design idea: ${esc(o.designChoice)}.</p>`:''}</div>`;}
export function gardenNotes(state){
 const g=ensureGarden(state);
 return `<section class="panel"><h2>Garden visits</h2><p>${g.visits.length} visit${g.visits.length===1?'':'s'} · ${g.visits.filter(v=>v.finished).length} at an ending</p><p class="tiny">Story tasks include context and guide prompts. Answer methods describe extra help, not a baseline assessment. Reading observations are reported separately. Unvisited subjects remain unknown; a project invitation does not establish completion or mastery.</p>${g.visits.length?`<div class="summary-links"><a class="secondary" href="#storm">Return to a visit</a><a href="#companions" class="text-button">Change companions</a></div>`:'<a href="#storm">Explore First Morning</a>'}</section><details class="panel"><summary>Story observations (${g.observations.length} recorded)</summary>${g.observations.map(storyEvidence).join('')||'<p>No story observations recorded yet.</p>'}</details>`;
}
